SELECT * FROM ( SELECT rownum AS rnum, R.* FROM ( SELECT A.user_idx, A.coach_idx, A.nickname, A.photo, ROUND(NVL(AVG(rt.rating), 0), 1) AS rating, COUNT(rt.content) AS review_count,
(SELECT CASE WHEN IS_CHAT = 'Y' THEN 'ACCEPTED' WHEN CHAT_APPLICANT = #{login_idx, jdbcType=INTEGER} AND IS_CHAT = 'N' THEN 'APPLIED' WHEN CHAT_APPLICANT != #{login_idx, jdbcType=INTEGER} AND IS_CHAT = 'N' THEN 'RECEIVED' ELSE 'NONE' END FROM MATCH WHERE (USER1_IDX = #{login_idx, jdbcType=INTEGER} AND USER2_IDX = A.user_idx) OR (USER1_IDX = A.user_idx AND USER2_IDX = #{login_idx, jdbcType=INTEGER})) as chatStatus, (SELECT CASE WHEN IS_MATCH = 'Y' THEN 'ACCEPTED' WHEN MATCH_APPLICANT = #{login_idx, jdbcType=INTEGER} AND IS_MATCH = 'N' THEN 'APPLIED' WHEN MATCH_APPLICANT != #{login_idx, jdbcType=INTEGER} AND IS_MATCH = 'N' THEN 'RECEIVED' ELSE 'NONE' END FROM MATCH WHERE (USER1_IDX = #{login_idx, jdbcType=INTEGER} AND USER2_IDX = A.user_idx) OR (USER1_IDX = A.user_idx AND USER2_IDX = #{login_idx, jdbcType=INTEGER})) as matchStatus
'NONE' as chatStatus, 'NONE' as matchStatus
FROM coach A LEFT JOIN coach_provide B ON A.coach_idx = B.coach_idx LEFT JOIN coach_region C ON A.coach_idx = C.coach_idx LEFT JOIN user_hashtag UH ON A.user_idx = UH.user_idx LEFT JOIN user_hashtag_like UHL ON A.user_idx = UHL.user_idx LEFT JOIN hashtag H ON UH.hashtag_idx = H.hashtag_idx LEFT JOIN hashtag H ON UHL.hashtag_idx = H.hashtag_idx LEFT JOIN review_coach rt ON A.user_idx = rt.reviewee_idx
(A.nickname LIKE '%' || #{keyword, jdbcType=VARCHAR} || '%' OR NVL(H.TAGS, ' ') LIKE '%' || #{keyword, jdbcType=VARCHAR} || '%') AND B.minor_field_idx = #{minorField} AND C.major_region_idx = #{majorRegion} AND C.minor_region_idx = #{minorRegion}
AND A.user_idx != #{login_idx, jdbcType=INTEGER}
GROUP BY A.user_idx, A.coach_idx, A.nickname, A.photo ORDER BY A.coach_idx DESC ) R WHERE rownum <= #{end} ) WHERE rnum >= #{start}

SELECT H.TAGS FROM hashtag H
JOIN user_hashtag UH ON H.hashtag_idx = UH.hashtag_idx
WHERE UH.user_idx = #{user_idx, jdbcType=INTEGER}

SELECT H.TAGS FROM hashtag H
JOIN user_hashtag_like UHL ON H.hashtag_idx = UHL.hashtag_idx
WHERE UHL.user_idx = #{user_idx, jdbcType=INTEGER}

